package com.medcore.backend.api.internaciones;import java.time.*;public record InternacionResponse(Long id,Long pacienteId,Long profesionalId,LocalDateTime fechaIngreso,LocalDateTime fechaAlta,String motivoInternacion,String diagnosticoIngreso,EstadoInternacion estado,Long camaId,Long admisionId){public static InternacionResponse from(Internacion i){return new InternacionResponse(i.getId(),i.getPacienteId(),i.getProfesionalId(),i.getFechaIngreso(),i.getFechaAlta(),i.getMotivoInternacion(),i.getDiagnosticoIngreso(),i.getEstado(),i.getCamaId(),i.getAdmisionId());}}
